package br.com.loja.order;

import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.List;
import java.util.UUID;

import org.springframework.dao.DuplicateKeyException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

import br.com.loja.catalog.ProductRepository;
import br.com.loja.checkout.CheckoutRequest;
import br.com.loja.checkout.CheckoutService;
import br.com.loja.checkout.OrderSummary;
import br.com.loja.common.ApiException;
import br.com.loja.common.ErrorCode;
import br.com.loja.customer.CustomerRepository;

@Service
public class OrderService {

    private static final String OK = "OK";
    private static final Duration PAYMENT_WINDOW = Duration.ofHours(48);

    private final CheckoutService checkout;
    private final OrderRepository orders;
    private final ProductRepository products;
    private final CustomerRepository customers;
    private final List<OrderEventListener> listeners;
    private final Clock clock;
    private final TransactionTemplate tx;

    OrderService(CheckoutService checkout, OrderRepository orders, ProductRepository products,
                 CustomerRepository customers, List<OrderEventListener> listeners, Clock clock,
                 PlatformTransactionManager transactionManager) {
        this.checkout = checkout;
        this.orders = orders;
        this.products = products;
        this.customers = customers;
        this.listeners = listeners;
        this.clock = clock;
        this.tx = new TransactionTemplate(transactionManager);
    }

    public Order create(CheckoutRequest request) {
        OrderSummary summary = checkout.summarize(request);
        List<OrderItem> items = request.items().stream()
                .map(i -> new OrderItem(i.sku(), i.quantity())).toList();
        Order order = new Order(UUID.randomUUID().toString(), request.customer().cpf(),
                OrderStatus.AWAITING_PAYMENT, Instant.now(clock).truncatedTo(ChronoUnit.SECONDS), summary, items,
                null, null, null);
        try {
            tx.executeWithoutResult(s -> customers.createIfAbsent(request.customer().cpf(), request.customer().email()));
        } catch (DuplicateKeyException e) {
            // outra máquina criou o mesmo cliente agora há pouco: está tudo certo
        }
        tx.executeWithoutResult(s -> orders.insert(order));
        return order;
    }

    public Order get(String id) {
        return orders.findById(id).orElseThrow(() -> new ApiException(ErrorCode.ORDER_NOT_FOUND));
    }

    private record PaymentResult(Order order, ErrorCode error) {
    }

    public Order confirmPayment(String id, String transactionId, String paidAtText) {
        PaymentResult result = tx.execute(s -> processPayment(id, transactionId, paidAtText));
        if (result.error() != null) {
            throw new ApiException(result.error(), HttpStatus.CONFLICT);
        }
        return result.order();
    }

    private PaymentResult processPayment(String id, String transactionId, String paidAtText) {
        Order order = lock(id);
        Instant paidAt = parseInstant(paidAtText);
        if (transactionId == null || transactionId.isBlank() || paidAt == null) {
            throw new ApiException(ErrorCode.INVALID_ORDER);
        }
        if (transactionId.equals(order.paymentTransactionId())) {
            return outcomeOf(order, order.paymentOutcome());
        }
        requireMove(order, OrderStatus.PAID);

        if (paidAt.isAfter(order.createdAt().plus(PAYMENT_WINDOW))) {
            return failPayment(order, transactionId, ErrorCode.ORDER_EXPIRED);
        }
        if (!products.reserve(order.items())) {
            return failPayment(order, transactionId, ErrorCode.INSUFFICIENT_STOCK);
        }
        orders.recordPayment(id, transactionId, OK, OrderStatus.PAID);
        Order paid = get(id);
        listeners.forEach(l -> l.onPaid(paid));
        return new PaymentResult(paid, null);
    }

    private PaymentResult failPayment(Order order, String transactionId, ErrorCode error) {
        orders.recordPayment(order.id(), transactionId, error.name(), OrderStatus.CANCELLED);
        Order cancelled = get(order.id());
        listeners.forEach(l -> l.onCancelled(cancelled, false));
        return new PaymentResult(cancelled, error);
    }

    private static PaymentResult outcomeOf(Order order, String outcome) {
        return new PaymentResult(order, OK.equals(outcome) ? null : ErrorCode.valueOf(outcome));
    }

    public Order ship(String id, String trackingCode) {
        return tx.execute(s -> {
            Order order = lock(id);
            if (trackingCode == null || trackingCode.isBlank()) {
                throw new ApiException(ErrorCode.INVALID_ORDER);
            }
            requireMove(order, OrderStatus.SHIPPED);
            orders.recordShipment(id, trackingCode);
            Order shipped = get(id);
            listeners.forEach(l -> l.onShipped(shipped));
            return shipped;
        });
    }

    public Order deliver(String id) {
        return tx.execute(s -> {
            Order order = lock(id);
            requireMove(order, OrderStatus.DELIVERED);
            orders.updateStatus(id, OrderStatus.DELIVERED);
            return get(id);
        });
    }

    public Order cancel(String id) {
        return tx.execute(s -> {
            Order order = lock(id);
            requireMove(order, OrderStatus.CANCELLED);
            boolean wasPaid = order.status() == OrderStatus.PAID;
            if (wasPaid) {
                products.release(order.items());
            }
            orders.updateStatus(id, OrderStatus.CANCELLED);
            Order cancelled = get(id);
            listeners.forEach(l -> l.onCancelled(cancelled, wasPaid));
            return cancelled;
        });
    }

    private Order lock(String id) {
        return orders.findByIdForUpdate(id).orElseThrow(() -> new ApiException(ErrorCode.ORDER_NOT_FOUND));
    }

    private static void requireMove(Order order, OrderStatus target) {
        if (!order.status().canMoveTo(target)) {
            throw new ApiException(ErrorCode.OPERATION_NOT_ALLOWED);
        }
    }

    private static Instant parseInstant(String text) {
        try {
            return text == null ? null : Instant.parse(text);
        } catch (java.time.format.DateTimeParseException e) {
            return null;
        }
    }
}
package br.com.loja.order;

import java.time.Instant;
import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.util.List;
import java.util.Optional;

import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Repository;

import br.com.loja.checkout.OrderSummary;

@Repository
public class OrderRepository {

    private static final String COLUMNS = """
            id, customer_cpf, status, created_at, tracking_code, payment_transaction_id, payment_outcome,
            products_subtotal, coupon_discount, shipping_cost, delivery_days, insurance, payment_adjustment,
            final_total, installments, installment_amount, next_purchase_credit, gift""";

    private final JdbcClient jdbc;

    OrderRepository(JdbcClient jdbc) {
        this.jdbc = jdbc;
    }

    public void insert(Order o) {
        OrderSummary s = o.summary();
        jdbc.sql("""
                INSERT INTO orders (id, customer_cpf, status, created_at, products_subtotal, coupon_discount,
                    shipping_cost, delivery_days, insurance, payment_adjustment, final_total, installments,
                    installment_amount, next_purchase_credit, gift)
                VALUES (:id, :cpf, :status, :createdAt, :subtotal, :discount, :shipping, :days, :insurance,
                    :adjustment, :total, :installments, :installment, :credit, :gift)""")
                .param("id", o.id()).param("cpf", o.customerCpf()).param("status", o.status().name())
                .param("createdAt", OffsetDateTime.ofInstant(o.createdAt(), ZoneOffset.UTC))
                .param("subtotal", s.productsSubtotal()).param("discount", s.couponDiscount())
                .param("shipping", s.shippingCost()).param("days", s.deliveryDays())
                .param("insurance", s.insurance()).param("adjustment", s.paymentAdjustment())
                .param("total", s.finalTotal()).param("installments", s.installments())
                .param("installment", s.installmentAmount()).param("credit", s.nextPurchaseCredit())
                .param("gift", s.gift()).update();
        int line = 0;
        for (OrderItem item : o.items()) {
            jdbc.sql("INSERT INTO order_items (order_id, line_no, sku, quantity) VALUES (:id, :line, :sku, :q)")
                    .param("id", o.id()).param("line", line++).param("sku", item.sku())
                    .param("q", item.quantity()).update();
        }
    }

    public Optional<Order> findById(String id) {
        return find("SELECT " + COLUMNS + " FROM orders WHERE id = :id", id);
    }

    /** Trava a linha do pedido até o fim da transação (serializa operações entre as duas máquinas). */
    public Optional<Order> findByIdForUpdate(String id) {
        return find("SELECT " + COLUMNS + " FROM orders WHERE id = :id FOR UPDATE", id);
    }

    private Optional<Order> find(String sql, String id) {
        return jdbc.sql(sql).param("id", id).query((rs, n) -> {
            List<OrderItem> items = jdbc
                    .sql("SELECT sku, quantity FROM order_items WHERE order_id = :id ORDER BY line_no")
                    .param("id", id).query((r, i) -> new OrderItem(r.getString("sku"), r.getInt("quantity")))
                    .list();
            OrderSummary summary = new OrderSummary(money(rs, "products_subtotal"), money(rs, "coupon_discount"),
                    money(rs, "shipping_cost"), rs.getInt("delivery_days"), money(rs, "insurance"),
                    money(rs, "payment_adjustment"), money(rs, "final_total"), rs.getInt("installments"),
                    money(rs, "installment_amount"), money(rs, "next_purchase_credit"), rs.getBoolean("gift"));
            Instant createdAt = rs.getObject("created_at", OffsetDateTime.class).toInstant();
            return new Order(rs.getString("id"), rs.getString("customer_cpf"),
                    OrderStatus.valueOf(rs.getString("status")), createdAt, summary, items,
                    rs.getString("tracking_code"), rs.getString("payment_transaction_id"),
                    rs.getString("payment_outcome"));
        }).optional();
    }

    private static java.math.BigDecimal money(java.sql.ResultSet rs, String column) throws java.sql.SQLException {
        return rs.getBigDecimal(column).setScale(2);
    }

    public void updateStatus(String id, OrderStatus status) {
        jdbc.sql("UPDATE orders SET status = :status WHERE id = :id")
                .param("status", status.name()).param("id", id).update();
    }

    public void recordPayment(String id, String transactionId, String outcome, OrderStatus status) {
        jdbc.sql("""
                UPDATE orders SET status = :status, payment_transaction_id = :tx, payment_outcome = :outcome
                WHERE id = :id""")
                .param("status", status.name()).param("tx", transactionId).param("outcome", outcome)
                .param("id", id).update();
    }

    public void recordShipment(String id, String trackingCode) {
        jdbc.sql("UPDATE orders SET status = :status, tracking_code = :code WHERE id = :id")
                .param("status", OrderStatus.SHIPPED.name()).param("code", trackingCode).param("id", id).update();
    }

    /** Já comprou de verdade: tem pedido pago, enviado ou entregue (cancelado não conta). */
    public boolean hasPurchaseByCustomer(String cpf) {
        return jdbc.sql("""
                SELECT COUNT(*) FROM orders
                WHERE customer_cpf = :cpf AND status IN ('PAID', 'SHIPPED', 'DELIVERED')""")
                .param("cpf", cpf).query(Long.class).single() > 0;
    }
}

